export async function handler(context, parameters) {
  const apiKey = context.secrets?.OPENAI_API_KEY;
  if (!apiKey) {
    return { success: false, error: 'Missing OPENAI_API_KEY in tool secrets' };
  }

  const backendUrl = context.secrets?.BACKEND_URL;
  if (!backendUrl) {
    return { success: false, error: 'Missing BACKEND_URL in tool secrets' };
  }

  const internalKey = context.secrets?.AICO_INTERNAL_API_KEY;

  // Build prompt with optional style
  const fullPrompt = parameters.style
    ? `${parameters.style}: ${parameters.prompt}`
    : parameters.prompt;

  console.log(`Generating image: ${fullPrompt.substring(0, 100)}...`);

  // 1. Generate image via DALL-E
  const genResponse = await fetch('https://api.openai.com/v1/images/generations', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: 'dall-e-3',
      prompt: fullPrompt,
      size: parameters.size || '1024x1024',
      quality: parameters.quality || 'standard',
      n: 1,
    }),
  });

  if (!genResponse.ok) {
    const err = await genResponse.text();
    return { success: false, error: `DALL-E API error (${genResponse.status}): ${err}` };
  }

  const genResult = await genResponse.json();
  const tempUrl = genResult.data?.[0]?.url;
  const revisedPrompt = genResult.data?.[0]?.revised_prompt;

  if (!tempUrl) {
    return { success: false, error: 'No image URL in DALL-E response' };
  }

  console.log('Image generated, storing as asset...');

  // 2. Store as permanent asset via backend API
  const storeHeaders = {
    'Content-Type': 'application/json',
    'X-Organization-Id': context.organizationId,
  };
  if (internalKey) {
    storeHeaders['Authorization'] = `Bearer ${internalKey}`;
  }

  const storeResponse = await fetch(`${backendUrl}/dev/api/assets/from-url`, {
    method: 'POST',
    headers: storeHeaders,
    body: JSON.stringify({ url: tempUrl }),
  });

  if (!storeResponse.ok) {
    const err = await storeResponse.text();
    return {
      success: true,
      output: {
        imageUrl: tempUrl,
        revisedPrompt,
        warning: `Image generated but asset storage failed (${storeResponse.status}): ${err}. Using temporary URL.`,
      },
    };
  }

  const asset = await storeResponse.json();
  console.log(`Image stored: ${asset.publicUrl}`);

  return {
    success: true,
    output: {
      imageUrl: asset.publicUrl,
      assetKey: asset.key,
      revisedPrompt,
    },
  };
}
